/* @lc app=leetcode id=851 lang=kotlin */ class Solution { fun loudAndRich(richer: Array<IntArray>, quiet: IntArray): IntArray = richer.groupBy({ it[1] }, { it[0] }).let { g -> IntArray(quiet.size) { -1 }.also { ans -> quiet.indices.forEach { f(it, g, quiet, ans) } } } fun f(x: Int, g: Map<Int, List<Int>>, q: IntArray, ans: IntArray): Int = if (ans[x] >= 0) ans[x] else (g[x].orEmpty().map { f(it, g, q, ans) } + x).minBy { q[it] }.also { ans[x] = it } }